package com.studysync.dao;
import com.studysync.model.Attendance; import com.studysync.util.DBConnection; import java.sql.*; import java.util.*;
public class AttendanceDAO { public int save(Attendance a)throws SQLException{String s="INSERT INTO attendance(user_id,subject,attended,total) VALUES(?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,a.getUserId());p.setString(2,a.getSubject());p.setInt(3,a.getAttended());p.setInt(4,a.getTotal());p.executeUpdate();ResultSet r=p.getGeneratedKeys();return r.next()?r.getInt(1):0;}} public List<Attendance> findByUser(int id)throws SQLException{List<Attendance> l=new ArrayList<Attendance>();String s="SELECT * FROM attendance WHERE user_id=? ORDER BY id DESC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,id);ResultSet r=p.executeQuery();while(r.next())l.add(new Attendance(r.getInt("id"),r.getInt("user_id"),r.getString("subject"),r.getInt("attended"),r.getInt("total")));}return l;} }
